```solidity: ERC2771Forwarder.sol
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import {ECDSA} from "../utils/cryptography/ECDSA.sol";
import {EIP712} from "../utils/cryptography/EIP712.sol";
import {SignatureChecker} from "../utils/cryptography/SignatureChecker.sol";
import {Nonces} from "../utils/Nonces.sol";
import {Address} from "../utils/Address.sol";

contract ERC2771Forwarder is EIP712, Nonces {
    using Address for address payable;

    struct ForwardRequestData {
        address from;
        address to;
        uint256 value;
        uint256 gas;
        uint256 deadline;
        bytes data;
        bytes signature;
    }

    error ERC2771UntrustfulTarget(address target, address forwarder);
    error ERC2771ForwarderInvalidSigner(address signer, address from);
    error ERC2771ForwarderExpiredRequest();
    error ERC2771ForwarderMismatchedValue(uint256 requestedValue, uint256 msgValue);
    error ERC2771ForwarderFailedCall();

    event ExecutedForwardRequest(
        address indexed signer,
        uint256 nonce,
        bool success
    );

    constructor(string memory name) EIP712(name, "1") {}

    function verify(ForwardRequestData calldata request) public virtual view returns (bool) {
        (bool isTrustedForwarder, bool active, bool signerMatch, ) = _validate(request);
        return isTrustedForwarder && active && signerMatch;
    }

    function execute(ForwardRequestData calldata request) public virtual payable {
        if (request.value != msg.value) {
            revert ERC2771ForwarderMismatchedValue(request.value, msg.value);
        }

        (bool success, ) = _execute(request, true);
        if (!success) {
            revert ERC2771ForwarderFailedCall();
        }
    }

    function executeBatch(ForwardRequestData[] calldata requests, address payable refundReceiver) public virtual payable {
        bool isAtomic = refundReceiver == address(0);

        uint256 requestedValue = 0;
        uint256 refundValue = 0;

        for (uint256 i = 0; i < requests.length; ++i) {
            requestedValue += requests[i].value;
            (bool success, ) = _execute(requests[i], isAtomic);
            if (!success) {
                refundValue += requests[i].value;
            }
        }

        if (requestedValue != msg.value) {
            revert ERC2771ForwarderMismatchedValue(requestedValue, msg.value);
        }

        if (refundValue > 0) {
            refundReceiver.sendValue(refundValue);
        }
    }

    function _validate(ForwardRequestData calldata request)
        internal
        virtual
        view
        returns (bool isTrustedForwarder, bool active, bool signerMatch, address signer)
    {
        isTrustedForwarder = _isTrustedByTarget(request.to);
        active = request.deadline >= block.timestamp;
        (bool isValid, address recovered) = _recoverForwardRequestSigner(request);
        signer = recovered;
        signerMatch = isValid && recovered == request.from;
    }

    function _recoverForwardRequestSigner(ForwardRequestData calldata request)
        internal
        virtual
        view
        returns (bool isValid, address signer)
    {
        bytes32 digest = _hashTypedDataV4(
            keccak256(
                abi.encode(
                    keccak256(
                        "ForwardRequest(address from,address to,uint256 value,uint256 gas,uint256 deadline,bytes data,uint256 nonce)"
                    ),
                    request.from,
                    request.to,
                    request.value,
                    request.gas,
                    request.deadline,
                    keccak256(request.data),
                    nonces(request.from)
                )
            )
        );

        return SignatureChecker.isValidSignatureNow(request.from, digest, request.signature);
    }

    function _execute(ForwardRequestData calldata request, bool requireValidRequest) internal virtual returns (bool success) {
        (bool isTrustedForwarder, bool active, bool signerMatch, address signer) = _validate(request);

        if (requireValidRequest) {
            if (!isTrustedForwarder) {
                revert ERC2771UntrustfulTarget(request.to, address(this));
            }
            if (!active) {
                revert ERC2771ForwarderExpiredRequest();
            }
            if (!signerMatch) {
                revert ERC2771ForwarderInvalidSigner(signer, request.from);
            }
        }

        if (isTrustedForwarder && active && signerMatch) {
            uint256 nonce = _useNonce(request.from);
            uint256 gas = request.gas;
            address to = request.to;
            uint256 value = request.value;
            bytes calldata data = request.data;

            uint256 gasLeft = gasleft();

            assembly ("memory-safe") {
                success := call(gas, to, value, add(data.offset, 32), data.length, 0, 0)
            }

            _checkForwardedGas(gasleft() - gasLeft, request);

            emit ExecutedForwardRequest(request.from, nonce, success);
        }
    }

    function _isTrustedByTarget(address target) private view returns (bool) {
        (bool success, bytes memory result) = target.staticcall(
            abi.encodeCall(ERC2771Forwarder.isTrustedForwarder, (address(this)))
        );
        return success && result.length >= 32 && abi.decode(result, (bool));
    }

    function _checkForwardedGas(uint256 gasLeft, ForwardRequestData calldata request) private pure {
        if (gasLeft < request.gas / 63) {
            assembly ("memory-safe") {
                invalid()
            }
        }
    }

    function isTrustedForwarder(address forwarder) public view returns (bool) {
        return forwarder == address(this);
    }
}
